import React from 'react';
import { BrowserRouter as Router, Route, Routes, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar';
import Home from './components/Home';
import CreateInvitation from './components/CreateInvitation';
import Login from './components/Login';
import { LoadScript } from "@react-google-maps/api";


const App = () => {
  const location = useLocation();

  // Don't show Navbar on the invitation view page
  const showNavbar = !location.pathname.includes('/invitation/');

  return (
    <div>
      {showNavbar && <Navbar />}
      <Routes>
      <LoadScript googleMapsApiKey="AIzaSyC_SWzf8RHvi-bp_15paSOy-ojqL0Bzdyw" libraries={mapLibraries}>

        <Route path="/" element={<Home />} />
        <Route path="/login" element={<Login />} />
        <Route path="/create" element={<CreateInvitation />} />
        </LoadScript>
      </Routes>
    </div>
  );
};

const AppWithRouter = () => (
  <Router>
    <App />
  </Router>
);

export default AppWithRouter;
